function CalendarGrid({ sessions, events, reviewDates, onSelect }: { sessions: { createdAt: Date }[]; events: { eventDate: string; title: string }[]; reviewDates: (Date | string | null)[]; onSelect: (date: string) => void }) {
  const ticket = useContext(RevivalTicketContext);
  const [ticketDate, setTicketDate] = useState<string | null>(null);
  const days = daysInCurrentMonth();
  const sessionDays = new Set(sessions.map(item => format(new Date(item.createdAt), "yyyy-MM-dd")));
  const reviewDaySet = new Set(reviewDates.filter(Boolean).map(date => format(new Date(date as Date | string), "yyyy-MM-dd")));
  const ticketDaySet = new Set(ticket?.usedDates ?? []);
  const today = new Date();
  const chooseDate = (date: string) => { if (ticket && ticket.revivalTickets > 0 && !ticketDaySet.has(date) && date <= format(today, "yyyy-MM-dd")) setTicketDate(date); else onSelect(date); };
  return <><div><div className="mb-3 flex items-center justify-between"><div><p className="font-semibold">{format(today, "yyyy年 M月", { locale: ja })}</p><p className="text-xs text-muted-foreground">日付をタップすると、詳細確認または復活チケットの使用を選べます。</p></div><Leaf className="h-5 w-5 text-emerald-500" /></div><div className="grid grid-cols-7 gap-1 text-center text-[10px] text-muted-foreground">{["日", "月", "火", "水", "木", "金", "土"].map(day => <span key={day}>{day}</span>)}</div><div className="mt-1 grid grid-cols-7 gap-1">{days.map((date, index) => { if (!date) return <div key={`blank-${index}`} />; const key = format(date, "yyyy-MM-dd"); const learned = sessionDays.has(key); const rescued = ticketDaySet.has(key); const event = events.find(item => item.eventDate === key); return <button type="button" key={key} onClick={() => chooseDate(key)} className={cn("relative flex aspect-square flex-col items-center justify-center rounded-xl text-xs transition active:scale-95", isSameDay(date, today) ? "ring-2 ring-primary/60" : "", rescued ? "bg-slate-300 text-slate-600 dark:bg-slate-700 dark:text-slate-200" : learned ? "bg-emerald-500/15 text-emerald-700 dark:text-emerald-300" : "bg-muted/55")}>{rescued ? <span className="text-[10px] font-bold">休</span> : learned ? <Sprout className="h-4 w-4" /> : <span>{date.getDate()}</span>}{reviewDaySet.has(key) && <span className="absolute right-1 top-1" title="SRS復習予定" aria-label="SRS復習予定"><RotateCcw className="h-3 w-3 text-violet-500" /></span>}{event && <span className="absolute bottom-1 h-1 w-1 rounded-full bg-amber-500" title={event.title} />}</button>; })}</div></div>{ticketDate && <div role="dialog" aria-modal="true" className="fixed inset-0 z-[75] flex items-end justify-center bg-black/40 p-3 sm:items-center"><Card className="w-full max-w-sm"><CardHeader><CardTitle>{format(new Date(`${ticketDate}T00:00:00`), "M月d日（E）", { locale: ja })}</CardTitle><CardDescription>この日の学習記録を確認するか、体調不良などのために復活チケットを使えます。</CardDescription></CardHeader><CardContent className="space-y-2"><Button className="w-full" onClick={() => { ticket?.useTicket(ticketDate); setTicketDate(null); }}>チケットを使用して灰色の救済日にする</Button><Button className="w-full" variant="outline" onClick={() => { onSelect(ticketDate); setTicketDate(null); }}>学習の詳細を見る</Button><Button className="w-full" variant="ghost" onClick={() => setTicketDate(null)}>閉じる</Button></CardContent></Card></div>}</>;
}

